'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp[0][0];
}
let seed = 1;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', 'y', ' x', '-y', '+z', 'w'];
const gen = (n, k) => Array.from({ length: rnd(n) }, () => alpha[rnd(k)]);

for (let iter = 0; iter < 20000; iter++) {
  const k = 1 + rnd(alpha.length);
  const a = gen(14, k), b = gen(14, k);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  assert.equal(s.filter((e) => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  for (let t = 1; t < s.length; t++) assert.ok(!(s[t - 1].op === 'insert' && s[t].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    assert.deepEqual(applyHunks(a, h), b);
    if (iter % 50 === 0) {
      // reversed-hunk application to b gives a
      const rev = h.map((x) => ({ oldStart: x.newStart, oldLines: x.newLines, newStart: x.oldStart, newLines: x.oldLines,
        lines: x.lines.map((l) => (l[0] === '+' ? '-' : l[0] === '-' ? '+' : ' ') + l.slice(1)) }));
      assert.deepEqual(applyHunks(b, rev), a);
    }
    for (let i = 0; i < h.length; i++) {
      const bad = JSON.parse(JSON.stringify(h));
      bad[i].newStart += 1;
      assert.throws(() => applyHunks(a, bad), new RegExp(`hunk ${i} does not apply`));
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}
assert.deepEqual(unifiedHunks(['a'], ['a']), []);
assert.deepEqual(unifiedHunks([], ['a']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+a'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['b'], { context: 0 }), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-a'] }]);
assert.throws(() => applyHunks(['q'], [{ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' z'] }]), /hunk 0 does not apply/);

// perf
const big = Array.from({ length: 20000 }, (_, i) => (i % 7 === 0 ? '}' : 'line ' + (i % 50)));
const big2 = big.slice(); big2[100] = 'changed'; big2.splice(9000, 3); big2.splice(15000, 0, 'new', '}');
let t0 = performance.now();
const h = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, h), big2);
console.log('small change 20k ms', (performance.now() - t0).toFixed(1));
t0 = performance.now(); diffLines(big, big.slice()); console.log('identical ms', (performance.now() - t0).toFixed(1));
const r1 = Array.from({ length: 20000 }, () => 'l' + rnd(3)), r2 = r1.map((x) => (rnd(100) === 0 ? 'm' : x));
t0 = performance.now(); const s = diffLines(r1, r2); console.log('repetitive 1% ms', (performance.now() - t0).toFixed(1), s.filter((e) => e.op !== 'equal').length);
console.log('ok');
